async function call(handler,path,options={}){const req={url:options.url||'/api/business'+path,query:options.query,params:options.params,method:options.method||'GET',headers:{...(options.method?{'origin':env.BUSINESS_ORIGIN,'content-type':'application/json'}:{}),...(options.cookie?{cookie:options.cookie}:{}),...options.headers},body:options.body};const headers={};let result;const res={setHeader:(k,v)=>{headers[k.toLowerCase()]=v;},status(status){this.statusCode=status;return this;},json(body){result={status:this.statusCode,body,headers};return result;},send(body){result={status:this.statusCode,body,headers};return result;}};await handler(req,res);return result;}
async function login(f){const r=await call(f.handler,'/login',{method:'POST',body:{email:'synthetic@example.invalid',password:'synthetic-only'}});assert.equal(r.status,200,JSON.stringify(r.body));return r.headers['set-cookie'].split(';')[0];}

test('disabled connection fails closed without upstream calls',async()=>{const f=fixture();const r=await call(createBusinessHandler({env:{...env,BUSINESS_ENABLED:'false'},fetchImpl:f.fetchImpl}),'/me');assert.equal(r.status,503);assert.equal(f.calls.length,0);});
test('login uses secure encrypted HttpOnly cookie; tokens never appear in JSON',async()=>{const f=fixture(),r=await call(f.handler,'/login',{method:'POST',body:{email:'synthetic@example.invalid',password:'synthetic-only'}});assert.equal(r.status,200);const c=r.headers['set-cookie'];for(const flag of ['Secure','HttpOnly','SameSite=Strict','Path=/'])assert.ok(c.includes(flag));assert.ok(!c.includes('ACCESS_TOKEN'));assert.ok(!JSON.stringify(r.body).includes('REFRESH_TOKEN'));const s=openSession(c.split(';')[0].slice(COOKIE.length+1),env.BUSINESS_COOKIE_KEY);assert.equal(s.tenant,A);assert.equal(s.access,'ACCESS_TOKEN');});
