test('reads use caller JWT and fixed tenant; arbitrary query filters are rejected',async()=>{const f=fixture(),c=await login(f);const r=await call(f.handler,'/data/requests?limit=25',{cookie:c});assert.equal(r.status,200);assert.equal(r.body.total,0);const read=f.calls.find(c=>c.url.pathname==='/rest/v1/requests');assert.equal(read.options.headers.Authorization,'Bearer ACCESS_TOKEN');assert.equal(read.options.headers['Accept-Profile'],'dqa_business');const denied=await call(f.handler,'/data/requests?tenant_id=eq.other',{cookie:c});assert.equal(denied.status,422);});
