test('revocation failure is never reported as server logout success',async()=>{const f=fixture(),c=await login(f);f.setFailRevocation(true);const r=await call(f.handler,'/logout',{method:'POST',body:{},cookie:c});assert.equal(r.status,503);assert.equal(r.body.error.code,'SESSION_REVOCATION_UNCONFIRMED');assert.ok(r.headers['set-cookie'].includes('Max-Age=0'));});
