test('client retries only reads after one single-flight refresh',async()=>{let fresh=false,refreshes=0,reads=0;const client=createBusinessClient(async(url)=>{if(url.endsWith('/refresh')){refreshes++;await new Promise(r=>setTimeout(r,5));fresh=true;return Response.json({authenticated:true});}reads++;return fresh?Response.json({data:[]}):Response.json({error:{code:'SESSION_REFRESH_REQUIRED'}},{status:401});});await Promise.all([client.request('/data/requests'),client.request('/me')]);assert.equal(refreshes,1);assert.equal(reads,4);});
test('client never automatically retries writes on network failure',async()=>{let count=0;const client=createBusinessClient(async()=>{count++;throw Error('offline');});await assert.rejects(client.request('/data/requests',{method:'POST',body:{}}),e=>e.code==='WRITE_OUTCOME_UNKNOWN'&&e.outcomeUnknown);assert.equal(count,1);});

