test('account save reaches Auth invitation only through a committed server-authorized intent',async()=>{
 const f=fixture(),cookie=await login(f),key='x.'+Buffer.from(JSON.stringify({role:'service_role',ref:'mmazbwzdiizabikmiily'})).toString('base64url')+'.synthetic';let invites=0;
 const handler=createBusinessHandler({env:{...env,BUSINESS_SUPABASE_SERVICE_ROLE_KEY:key},fetchImpl:async(raw,o)=>{const p=new URL(raw).pathname,b=o.body?JSON.parse(o.body):{};
  if(p.endsWith('/save_access_with_invitation')){assert.equal(o.headers.Authorization,'Bearer ACCESS_TOKEN');return Response.json({state:'SAVED',operation_id:accessWrite.operation_id,invitation:{state:'QUEUED',operation_id:accessWrite.operation_id}});}
  if(p.endsWith('/claim_account_invitation')){assert.equal(o.headers.Authorization,'Bearer '+key);assert.equal(b.p_actor,U);assert.equal(b.p_tenant,A);return Response.json({state:'DISPATCH_GRANTED',operation_id:accessWrite.operation_id,dispatch_id:maintenanceId,email:'db-recipient@example.invalid'});}
  if(p==='/auth/v1/invite'){invites++;assert.deepEqual(b,{email:'db-recipient@example.invalid'});return Response.json({id:U,email:'db-recipient@example.invalid'});}
  if(p.endsWith('/finish_account_invitation'))return Response.json({state:b.p_state,code:b.p_code,operation_id:b.p_id});return f.fetchImpl(raw,o);
 }});
 const r=await call(handler,'/access',{cookie,method:'POST',body:{action:'save',...accessWrite}});assert.equal(r.status,200);assert.equal(r.body.data.state,'SAVED');assert.equal(r.body.data.invitation.state,'SENT');assert.equal(invites,1);assert.ok(!JSON.stringify(r.body).includes(key));
});
