const recoveryBody={operation_id:'ef000000-0000-4000-8000-000000000030',email:'synthetic@example.invalid'};
function recoveryFixture({available=false,eligible=true,mailStatus=200,prepareFails=false}={}){
 const base=fixture(),events=[];
 const fetchImpl=async(url,o)=>{const p=new URL(url).pathname,b=o.body?JSON.parse(o.body):{};
  if(p.endsWith('/public_account_entry_status')){events.push('entry');assert.equal(o.headers.apikey,env.BUSINESS_SUPABASE_SERVICE_ROLE_KEY);return Response.json({activation_available:available});}
  if(p.endsWith('/prepare_password_recovery')){events.push('prepare');assert.match(b.p_client_hash,/^[a-f0-9]{64}$/);assert.equal(o.headers.Authorization,'Bearer '+env.BUSINESS_SUPABASE_SERVICE_ROLE_KEY);if(prepareFails)throw Error('offline');return Response.json(eligible?{dispatch:true,email:b.p_email,operation_id:b.p_operation}:{dispatch:false});}
  if(p==='/auth/v1/recover'){events.push('mail');assert.equal(new URL(url).searchParams.get('redirect_to'),env.BUSINESS_ORIGIN+'/account/reset-password');assert.deepEqual(b,{email:'synthetic@example.invalid'});assert.equal(o.headers.Authorization,undefined);return Response.json({}, {status:mailStatus});}
  if(p.endsWith('/finish_password_recovery')){events.push(b.p_state);return Response.json(true);}
  return base.fetchImpl(url,o);
 };return {...base,events,handler:createBusinessHandler({env,fetchImpl})};
}
