// Assistant commands are handled before AI routing, through authenticated tenant RPCs.
function commandFixture({denied=false,wrong=false,unknown=false}={}){
 const base=fixture(),events=[];const handler=createBusinessHandler({env,fetchImpl:async(raw,o={})=>{const p=new URL(raw).pathname,b=o.body?JSON.parse(o.body):{};
 if(p==='/auth/v1/token'&&b.password==='restart-test-password'){events.push('reauth');return wrong?Response.json({message:'invalid'}, {status:400}):Response.json({user:{id:U,email:'synthetic@example.invalid'},access_token:'COMMAND_EPHEMERAL',refresh_token:'COMMAND_EPHEMERAL_REFRESH'});}
 if(p==='/auth/v1/logout'&&o.headers.Authorization==='Bearer COMMAND_EPHEMERAL'){events.push('revoke-verification');return new Response(null,{status:204});}
 const rpc=p.split('/').at(-1);
 if(['assistant_virtual_requests','preview_assistant_command','assistant_command_result','execute_assistant_cleanup','prepare_assistant_restart','complete_assistant_restart'].includes(rpc)){
  events.push({rpc,body:b,authorization:o.headers.Authorization});assert.equal(b.p_tenant,A);
  if(denied)return Response.json({message:'COMMAND_ADMIN_REQUIRED'},{status:403});
  if(rpc==='prepare_assistant_restart')return Response.json({reauth_granted:true});
  if(rpc==='complete_assistant_restart'){assert.equal(o.headers.Authorization,'Bearer '+env.BUSINESS_SUPABASE_SERVICE_ROLE_KEY);assert.equal(b.p_actor,U);assert.ok(!('password' in b));if(unknown)throw Error('lost command acknowledgement');return Response.json({state:b.p_outcome==='DELETE'?'SAVED':'REJECTED',action:'RESTART',code:b.p_outcome==='DELETE'?undefined:'ADMIN_PASSWORD_INVALID'});}
  if(rpc==='execute_assistant_cleanup'&&unknown)throw Error('lost cleanup acknowledgement');
  return Response.json(rpc==='assistant_virtual_requests'?{source:'DATABASE',total:5,deduplicated:true}:{state:'SAVED'});
 }
 return base.fetchImpl(raw,o);
 }});return {base,handler,events};
}
const commandBody={id:'ef990000-0000-4000-8000-000000000001',fingerprint:'a'.repeat(64),confirmation:'初始化系統',password:'restart-test-password'};
