test('native template library requires a session and receives its tenant from the cookie',async()=>{const f=fixture();assert.equal((await call(f.handler,'/templates/blank')).status,401);const cookie=await login(f),r=await call(f.handler,'/templates/blank',{cookie});assert.equal(r.status,200);assert.equal(r.body.data.builtin_visible,true);});
test('native template upload validates actual Excel and hash before writing',async()=>{const f=fixture(),cookie=await login(f),body=await templateBody(),r=await call(f.handler,'/templates/blank/save',{cookie,method:'POST',body});assert.equal(r.status,200,JSON.stringify(r.body));assert.equal(r.body.data.state,'SAVED');const writes=f.calls.filter(x=>x.url.pathname.endsWith('/save_blank_request_template'));assert.equal(writes.length,1);assert.equal(JSON.parse(writes[0].options.body).p_name,body.name);});
test('native template upload accepts print-bounded Excel with empty formatting beyond column 48 and preserves original bytes',async()=>{const f=fixture(),cookie=await login(f),body=await templateBody(),{excelModule}=await import('../src/reportWorkbook.mjs'),{createHash}=await import('node:crypto'),Excel=await excelModule(),book=new Excel.Workbook();await book.xlsx.load(Buffer.from(body.content,'base64'));const sheet=book.worksheets[0];sheet.pageSetup.printArea='A1:AR45';sheet.getCell('AQ43').value='簽名欄位';sheet.getCell('CK45').font={bold:true};sheet.mergeCells('CB40:CK40');const bytes=Buffer.from(await book.xlsx.writeBuffer());body.content=bytes.toString('base64');body.sha256=createHash('sha256').update(bytes).digest('hex');const r=await call(f.handler,'/templates/blank/save',{cookie,method:'POST',body});assert.equal(r.status,200,JSON.stringify(r.body));const writes=f.calls.filter(x=>x.url.pathname.endsWith('/save_blank_request_template'));assert.equal(writes.length,1);assert.equal(JSON.parse(writes[0].options.body).p_content,body.content);});
test('native template upload cannot include formulas or lie about the hash',async()=>{const f=fixture(),cookie=await login(f);for(const body of [await templateBody(true),{...await templateBody(),sha256:'a'.repeat(64)}]){const r=await call(f.handler,'/templates/blank/save',{cookie,method:'POST',body});assert.equal(r.status,422);assert.equal(r.body.error.code,'TEMPLATE_FILE_INVALID');}assert.equal(f.calls.filter(x=>x.url.pathname.endsWith('/save_blank_request_template')).length,0);});
test('nonadmin upload and delete are rejected before any template write',async()=>{const f=fixture(),cookie=await login(f);f.setMaintenanceError('TEMPLATE_ADMIN_REQUIRED');const r=await call(f.handler,'/templates/blank/save',{cookie,method:'POST',body:await templateBody()});assert.equal(r.status,403);assert.equal(f.calls.filter(x=>x.url.pathname.endsWith('/save_blank_request_template')).length,0);const d=await call(f.handler,'/templates/blank/delete',{cookie,method:'POST',body:{operation_id:commandBody.id,id:'BLANK',revision:0}});assert.equal(d.status,403);});
test('template mutation rejects forged scope and unknown fields',async()=>{const f=fixture(),cookie=await login(f),r=await call(f.handler,'/templates/blank/delete',{cookie,method:'POST',body:{operation_id:commandBody.id,id:'BLANK',revision:0,tenant_id:A}});assert.equal(r.status,422);assert.equal(f.calls.filter(x=>x.url.pathname.endsWith('/delete_blank_request_template')).length,0);});
test('template delete lost acknowledgement is reported as unknown without replay',async()=>{const f=fixture(),cookie=await login(f);f.setFailWrite(true);const r=await call(f.handler,'/templates/blank/delete',{cookie,method:'POST',body:{operation_id:commandBody.id,id:'BLANK',revision:0}});assert.equal(r.body.outcome_unknown,true);assert.equal(f.calls.filter(x=>x.url.pathname.endsWith('/delete_blank_request_template')).length,1);});
test('template file and result use authenticated four-segment routes',async()=>{const f=fixture(),cookie=await login(f);for(const section of ['file','result']){const r=await call(f.handler,'/templates/blank/'+section+'/'+commandBody.id,{cookie});assert.equal(r.status,200);}assert.equal(f.calls.filter(x=>/blank_request_template_(file|result)$/.test(x.url.pathname)).length,2);});

test('workspace default binding sends only tenant-scoped immutable template identity and hash',async()=>{const f=fixture(),cookie=await login(f),body={operation_id:commandBody.id,id:'ef880000-0000-4000-8000-000000000001',revision:2,sha256:'a'.repeat(64)},r=await call(f.handler,'/templates/blank/default',{cookie,method:'POST',body});assert.equal(r.status,200);assert.equal(r.body.data.state,'DEFAULT_SET');const row=f.calls.find(x=>x.url.pathname.endsWith('/set_blank_request_template_default'));assert.deepEqual(JSON.parse(row.options.body),{p_tenant:A,p_operation:body.operation_id,p_id:body.id,p_revision:2,p_sha256:body.sha256});});
test('workspace default binding enforces admin and conflict errors without claiming success',async()=>{for(const [code,status]of [['TEMPLATE_ADMIN_REQUIRED',403],['TEMPLATE_IN_USE',409],['REVISION_CONFLICT',409]]){const f=fixture(),cookie=await login(f);f.setMaintenanceError(code);const r=await call(f.handler,'/templates/blank/default',{cookie,method:'POST',body:{operation_id:commandBody.id,id:'BLANK',revision:0,sha256:null}});assert.equal(r.status,status);assert.equal(r.body.error.code,code);}});
test('workspace default binding rejects forged tenant and malformed identifiers before writing',async()=>{const f=fixture(),cookie=await login(f);for(const extra of [{tenant_id:A},{revision:-1},{sha256:'bad'},{id:'CUSTOM'}]){const r=await call(f.handler,'/templates/blank/default',{cookie,method:'POST',body:{operation_id:commandBody.id,id:'BLANK',revision:0,sha256:null,...extra}});assert.equal(r.status,422);}assert.equal(f.calls.filter(x=>x.url.pathname.endsWith('/set_blank_request_template_default')).length,0);});
test('workspace default binding acknowledgement loss is never replayed',async()=>{const f=fixture(),cookie=await login(f);f.setFailWrite(true);const r=await call(f.handler,'/templates/blank/default',{cookie,method:'POST',body:{operation_id:commandBody.id,id:'BLANK',revision:0,sha256:null}});assert.equal(r.body.outcome_unknown,true);assert.equal(f.calls.filter(x=>x.url.pathname.endsWith('/set_blank_request_template_default')).length,1);});

const bindingTrial='a3000000-0000-0000-0000-000000000001';
async function trialBindingBody(){const b=await templateBody();return {operation_id:b.operation_id,trial_id:bindingTrial,expected_revision:0,file_id:b.id,name:b.name,version:b.version,sha256:b.sha256,content:b.content};}
test('trial binding upload is authenticated and uses the cookie tenant',async()=>{const f=fixture();assert.equal((await call(f.handler,'/trial-templates')).status,401);const cookie=await login(f),body=await trialBindingBody(),r=await call(f.handler,'/trial-templates/save',{cookie,method:'POST',body});assert.equal(r.status,200,JSON.stringify(r.body));const writes=f.calls.filter(x=>x.url.pathname.endsWith('/save_trial_template_binding'));assert.equal(writes.length,1);const saved=JSON.parse(writes[0].options.body);assert.equal(saved.p_tenant,A);assert.equal(saved.p_trial,bindingTrial);assert.equal(saved.p_content,body.content);});
test('trial binding authorizes managers before parsing invalid Excel',async()=>{const f=fixture(),cookie=await login(f);f.setMaintenanceError('TRIAL_TEMPLATE_ADMIN_REQUIRED');const r=await call(f.handler,'/trial-templates/save',{cookie,method:'POST',body:await trialBindingBody()});assert.equal(r.status,403);assert.equal(f.calls.filter(x=>x.url.pathname.endsWith('/save_trial_template_binding')).length,0);});
test('trial binding rejects forged actor tenant and malformed revision',async()=>{const f=fixture(),cookie=await login(f),body=await trialBindingBody();for(const extra of [{tenant_id:A},{actor_id:U},{expected_revision:-1},{expected_revision:2147483648}]){const r=await call(f.handler,'/trial-templates/save',{cookie,method:'POST',body:{...body,...extra}});assert.equal(r.status,422);}assert.equal(f.calls.filter(x=>x.url.pathname.endsWith('/save_trial_template_binding')).length,0);});
test('trial binding rejects bad content hash without storing a file',async()=>{const f=fixture(),cookie=await login(f),body=await trialBindingBody(),r=await call(f.handler,'/trial-templates/save',{cookie,method:'POST',body:{...body,sha256:'a'.repeat(64)}});assert.equal(r.status,422);assert.equal(r.body.error.code,'TRIAL_TEMPLATE_FILE_INVALID');assert.equal(f.calls.filter(x=>x.url.pathname.endsWith('/save_trial_template_binding')).length,0);});
test('trial binding rejects a different declared trial in the actual workbook',async()=>{const f=fixture(),cookie=await login(f),body=await trialBindingBody(),{excelModule}=await import('../src/reportWorkbook.mjs'),{createHash}=await import('node:crypto'),Excel=await excelModule(),book=new Excel.Workbook();book.addWorksheet('範本資訊').addRow(['試驗範本','Unrelated trial']);const bytes=Buffer.from(await book.xlsx.writeBuffer());const r=await call(f.handler,'/trial-templates/save',{cookie,method:'POST',body:{...body,sha256:createHash('sha256').update(bytes).digest('hex'),content:bytes.toString('base64')}});assert.equal(r.status,422);assert.equal(f.calls.filter(x=>x.url.pathname.endsWith('/save_trial_template_binding')).length,0);});
test('trial delivery passes only document and attempt to scoped claim and ack RPCs',async()=>{const f=fixture(),cookie=await login(f);for(const action of ['claim','ack']){const r=await call(f.handler,'/trial-templates/'+action,{cookie,method:'POST',body:{document_id:commandBody.id,attempt:commandBody.id,...(action==='claim'?{manual:true}:{})}});assert.equal(r.status,200);assert.equal(r.body.data.attempt,commandBody.id);}const claimed=f.calls.find(x=>x.url.pathname.endsWith('/claim_trial_template_delivery'));assert.equal(JSON.parse(claimed.options.body).p_manual,true);const get=await call(f.handler,'/trial-templates/request/'+commandBody.id,{cookie});assert.equal(get.body.data.has_template,false);});
test('trial delivery claim cannot forge executor or workspace and checks access errors',async()=>{const f=fixture(),cookie=await login(f);for(const extra of [{member_id:A},{tenant_id:A},{manual:'yes'}])assert.equal((await call(f.handler,'/trial-templates/claim',{cookie,method:'POST',body:{document_id:commandBody.id,attempt:commandBody.id,...extra}})).status,422);f.setMaintenanceError('TRIAL_TEMPLATE_ACCESS_DENIED');assert.equal((await call(f.handler,'/trial-templates/request/'+commandBody.id,{cookie})).status,403);});
test('trial binding lost acknowledgement is unknown and never retried',async()=>{const f=fixture(),cookie=await login(f);f.setFailWrite(true);const r=await call(f.handler,'/trial-templates/save',{cookie,method:'POST',body:await trialBindingBody()});assert.equal(r.body.outcome_unknown,true);assert.equal(f.calls.filter(x=>x.url.pathname.endsWith('/save_trial_template_binding')).length,1);});
async function mappingBody(){const {excelModule}=await import('../src/reportWorkbook.mjs'),{createHash}=await import('node:crypto'),Excel=await excelModule(),book=new Excel.Workbook();book.addWorksheet('資料').getCell('A1').value='產品';const bytes=Buffer.from(await book.xlsx.writeBuffer());return {source:{id:bindingTrial,name:'合成報告.xlsx',sha256:createHash('sha256').update(bytes).digest('hex'),byteLength:bytes.length,content:bytes.toString('base64')},body:{operation_id:commandBody.id,kind:'REPORT',file_id:bindingTrial,revision:0,sha256:createHash('sha256').update(bytes).digest('hex'),mapping:[{field:'productCode',sheet:'資料',cell:'B2'}]}};}
test('cell mapping API requires authentication and managers before workbook parse',async()=>{const f=fixture();assert.equal((await call(f.handler,'/document-mappings')).status,401);const cookie=await login(f),{body}=await mappingBody();f.setMaintenanceError('DOCUMENT_MAPPING_ACCESS_DENIED');assert.equal((await call(f.handler,'/document-mappings/save',{cookie,method:'POST',body})).status,403);assert.equal(f.calls.filter(c=>c.url.pathname.endsWith('/save_document_mapping')).length,0);});
test('cell mapping API validates sheet and targets then saves using cookie tenant',async()=>{const f=fixture(),cookie=await login(f),{source,body}=await mappingBody();f.setMapping(source);const r=await call(f.handler,'/document-mappings/save',{cookie,method:'POST',body});assert.equal(r.status,200,JSON.stringify(r.body));const write=f.calls.find(c=>c.url.pathname.endsWith('/save_document_mapping'));assert.equal(JSON.parse(write.options.body).p_tenant,A);assert.deepEqual(JSON.parse(write.options.body).p_mapping,body.mapping);});
test('cell mapping refuses unknown fields, foreign scope, bad coordinates and absent worksheets',async()=>{const f=fixture(),cookie=await login(f),{source,body}=await mappingBody();f.setMapping(source);for(const b of [{...body,tenant_id:A},{...body,revision:-1},{...body,mapping:[{...body.mapping[0],sheet:'missing'}]},{...body,mapping:[{...body.mapping[0],cell:'AW1'}]}])assert.equal((await call(f.handler,'/document-mappings/save',{cookie,method:'POST',body:b})).status,422);assert.equal(f.calls.filter(c=>c.url.pathname.endsWith('/save_document_mapping')).length,0);});
test('cell mapping unknown write is never automatically retried and can be read back',async()=>{const f=fixture(),cookie=await login(f),{source,body}=await mappingBody();f.setMapping(source);f.setFailWrite(true);const r=await call(f.handler,'/document-mappings/save',{cookie,method:'POST',body});assert.equal(r.body.outcome_unknown,true);assert.equal(f.calls.filter(c=>c.url.pathname.endsWith('/save_document_mapping')).length,1);f.setFailWrite(false);assert.equal((await call(f.handler,'/document-mappings/result/'+commandBody.id,{cookie})).body.data.state,'SAVED');});
test('case document generation uses database payload and rejects request query overrides',async()=>{const f=fixture(),cookie=await login(f),{source,body}=await mappingBody();f.setMapping({...source,has_template:true,kind:'REQUEST',request_code:'REQ-SYNTHETIC',mapping:body.mapping,payload:{request_legacy_id:'REQ-SYNTHETIC',product_code:'A08',form_details:{}},department:'固定部門'});const r=await call(f.handler,'/document-mappings/case/REQUEST/'+commandBody.id,{cookie});assert.equal(r.status,200,JSON.stringify(r.body));assert.equal(r.body.data.source_sha256,source.sha256);const {excelModule}=await import('../src/reportWorkbook.mjs'),Excel=await excelModule(),book=new Excel.Workbook();await book.xlsx.load(Buffer.from(r.body.data.content,'base64'));assert.equal(book.getWorksheet('資料').getCell('B2').text,'A08');assert.equal(book.getWorksheet('資料').sheetProtection.sheet,true);assert.equal((await call(f.handler,'/document-mappings/case/REQUEST/'+commandBody.id+'?productCode=FORGED',{cookie})).status,422);});
test('missing mapping and blank form used as report remain explicit errors',async()=>{const f=fixture(),cookie=await login(f);for(const code of ['DOCUMENT_MAPPING_REQUIRED','TRIAL_TEMPLATE_REQUEST_FORM_DENIED','ORIGINAL_SOURCE_REQUIRED']){f.setMaintenanceError(code);const r=await call(f.handler,'/trial-templates/request/'+commandBody.id,{cookie});assert.equal(r.status,422);assert.equal(r.body.error.code,code);}});
test('new checkbox and independent source-content fields pass mapping validation without accepting arbitrary fields',async()=>{const f=fixture(),cookie=await login(f),{source,body}=await mappingBody();f.setMapping(source);for(const field of ['judgementRequiredCheck','judgementNotRequiredCheck','purposeEV','purposeOtherSelected','purposeOtherContent','sourceCustomerContent']){const r=await call(f.handler,'/document-mappings/save',{cookie,method:'POST',body:{...body,mapping:[{...body.mapping[0],field}]}});assert.equal(r.status,200,field+':'+JSON.stringify(r.body));}const r=await call(f.handler,'/document-mappings/save',{cookie,method:'POST',body:{...body,mapping:[{...body.mapping[0],field:'arbitraryScript'}]}});assert.equal(r.status,422);});
test('missing other-purpose explanation is an explicit submission error',async()=>{const f=fixture(),cookie=await login(f);f.setMaintenanceError('OTHER_PURPOSE_REQUIRED');const r=await call(f.handler,'/trial-templates/request/'+commandBody.id,{cookie});assert.equal(r.status,422);assert.equal(r.body.error.code,'OTHER_PURPOSE_REQUIRED');});
test('native stage routes separate canonical commands from strictly typed inputs',async()=>{const f=fixture(),cookie=await login(f);for(const path of ['/workflow/prepare','/workflow/execute']){const command={...workflowWrite.command,action:'LMS_APPROVE',template_fields:{allowed:'yes',sampleCode:'SYN-001'}};assert.equal((await call(f.handler,path,{method:'POST',cookie,body:{...workflowWrite,command}})).status,200);const c=f.calls.findLast(c=>c.url.pathname.endsWith(path.endsWith('prepare')?'prepare_request_template_operation':'execute_request_template_operation'));const body=JSON.parse(c.options.body);assert.equal(body.p_tenant,A);assert.deepEqual(body.p_fields,command.template_fields);assert.equal(Object.hasOwn(body.p_command,'template_fields'),false);}for(const path of ['/execution/prepare','/execution/execute']){const command={...humanBody.command,action:'RECEIVE',template_fields:{sampleCorrect:'yes',sampleQuantity:3}};assert.equal((await call(f.handler,path,{method:'POST',cookie,body:{...humanBody,command}})).status,200);const c=f.calls.findLast(c=>c.url.pathname.endsWith(path.endsWith('prepare')?'prepare_human_template_operation':'execute_human_template_operation')),body=JSON.parse(c.options.body);assert.deepEqual(body.p_fields,{sampleCorrect:'yes',sampleQuantity:3});assert.equal(Object.hasOwn(body.p_command,'template_fields'),false);}});
test('stage inputs cannot be attached to return, report or spoofed actor/image commands',async()=>{const f=fixture(),cookie=await login(f);for(const [path,body] of [['/workflow/prepare',{...workflowWrite,command:{...workflowWrite.command,action:'RETURN',template_fields:{allowed:'yes'}}}],['/workflow/prepare',{...workflowWrite,command:{...workflowWrite.command,action:'LMS_APPROVE',template_fields:{signature_data:'spoof'}}}],['/execution/prepare',{...humanBody,command:{...humanBody.command,action:'REPORT_SUBMIT',template_fields:{sampleCorrect:'yes'}}}],['/execution/prepare',{...humanBody,command:{...humanBody.command,action:'COMPLETE',template_fields:{executionAbnormal:'pending'}}}]]){const r=await call(f.handler,path,{method:'POST',cookie,body});assert.equal(r.status,422);assert.equal(r.body.error.code,'TEMPLATE_STAGE_FIELDS_INVALID');}assert.equal(f.calls.some(c=>c.url.pathname.includes('_template_operation')),false);});
test('stage context binds tenant and hides input data on denied access',async()=>{const f=fixture(),cookie=await login(f);assert.equal((await call(f.handler,'/document-mappings/stage/'+maintenanceId,{cookie})).status,200);f.setMaintenanceError('DOCUMENT_MAPPING_ACCESS_DENIED');const r=await call(f.handler,'/document-mappings/stage/'+maintenanceId,{cookie});assert.equal(r.status,403);assert.equal(r.body.data,undefined);});
test('unknown stage write outcome requires readback and is never retried',async()=>{const f=fixture(),cookie=await login(f);f.setFailWrite(true);const r=await call(f.handler,'/execution/execute',{method:'POST',cookie,body:{...humanBody,command:{...humanBody.command,action:'RECEIVE',template_fields:{sampleCorrect:'yes'}}}});assert.equal(r.status,503);assert.equal(r.body.outcome_unknown,true);assert.equal(f.calls.filter(c=>c.url.pathname.endsWith('execute_human_template_operation')).length,1);});

const sampleSave={operation_id:maintenanceId,request_id:maintenanceId,document_id:maintenanceId,request_revision:3,revision:0,code:'SAMPLE-1'};
test('preapproval reads and sample-number mutation use fixed tenant and caller identity',async()=>{const f=fixture(),cookie=await login(f);for(const [path,options]of [['/preapproval/request/'+maintenanceId,{}],['/preapproval/number',{method:'POST',body:sampleSave}],['/preapproval/result/'+maintenanceId,{}]])assert.equal((await call(f.handler,path,{cookie,...options})).status,200);const args=JSON.parse(f.calls.find(c=>c.url.pathname.endsWith('/save_preapproval_sample_number')).options.body);assert.equal(args.p_code,'SAMPLE-1');assert.equal(args.p_request_revision,3);});
test('sample-number endpoints reject tenant substitution, invalid revisions, queries and foreign origins',async()=>{const f=fixture(),cookie=await login(f);for(const body of [{...sampleSave,tenant_id:'other'},{...sampleSave,revision:-1},{...sampleSave,request_revision:0},{...sampleSave,code:' '},{...sampleSave,code:'a'.repeat(121)}])assert.equal((await call(f.handler,'/preapproval/number',{cookie,method:'POST',body})).status,422);assert.equal((await call(f.handler,'/preapproval/request/'+maintenanceId+'?tenant=other',{cookie})).status,422);assert.equal((await call(f.handler,'/preapproval/number',{cookie,method:'POST',body:sampleSave,headers:{origin:'https://foreign.invalid'}})).status,403);assert.equal(f.calls.filter(c=>c.url.pathname.endsWith('/save_preapproval_sample_number')).length,0);});
test('lost sample-number acknowledgement never resends and retains read-only result lookup',async()=>{const f=fixture(),cookie=await login(f);f.setFailWrite(true);const r=await call(f.handler,'/preapproval/number',{cookie,method:'POST',body:sampleSave});assert.equal(r.body.outcome_unknown,true);assert.equal(f.calls.filter(c=>c.url.pathname.endsWith('/save_preapproval_sample_number')).length,1);assert.equal((await call(f.handler,'/preapproval/result/'+maintenanceId,{cookie})).status,200);});
test('first approval sends plan revision separately from canonical command',async()=>{const f=fixture(),cookie=await login(f);const command={request_id:maintenanceId,expected_revision:3,action:'LMS_APPROVE',signature_data:'',comment:'',template_fields:{allowed:'yes'},plan_revision:2};assert.equal((await call(f.handler,'/workflow/prepare',{cookie,method:'POST',body:{operation_id:maintenanceId,command}})).status,200);const args=JSON.parse(f.calls.find(c=>c.url.pathname.endsWith('/prepare_request_template_operation')).options.body);assert.equal(args.p_plan_revision,2);assert.equal(args.p_command.plan_revision,undefined);assert.equal(args.p_command.template_fields,undefined);assert.deepEqual(args.p_fields,{allowed:'yes'});});
